package com.hospital.smartqueue.doctor.api; import com.hospital.smartqueue.doctor.application.DoctorService; import com.hospital.smartqueue.doctor.domain.Doctor; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/hospitals/{hospitalId}/doctors") public class DoctorController{private final DoctorService s;public DoctorController(DoctorService x){s=x;}public record Request(@NotBlank String doctorCode,@NotBlank String name,@NotBlank String specialization,@NotBlank String professionalRegistrationNumber,Doctor.Status status){}public record Response(UUID id,UUID hospitalId,Doctor.Status status){}@PostMapping public ResponseEntity<Response> create(@PathVariable UUID hospitalId,@Valid @RequestBody Request r){var d=s.register(hospitalId,r.doctorCode(),r.name(),r.specialization(),r.professionalRegistrationNumber(),r.status());return ResponseEntity.status(HttpStatus.CREATED).body(new Response(d.getId(),d.getHospitalId(),d.getStatus()));}@GetMapping public List<Response> list(@PathVariable UUID hospitalId){return s.list(hospitalId).stream().map(d->new Response(d.getId(),d.getHospitalId(),d.getStatus())).toList();}@PatchMapping("/{doctorId}/status")public Response status(@PathVariable UUID hospitalId,@PathVariable UUID doctorId,@RequestBody Doctor.Status st){var d=s.status(hospitalId,doctorId,st);return new Response(d.getId(),d.getHospitalId(),d.getStatus());}}
